/* Five-part presentation route; the existing lab remains available below it. */
:root{--reading-font:'Times New Roman','Heiti SC';--serif:var(--reading-font);--sans:var(--reading-font);--header-height:134px}
body{font-family:var(--reading-font)}
body *{font-family:var(--reading-font)!important}
html{scroll-padding-top:calc(var(--header-height) + 20px)}
.navlinks{display:block;overflow:visible;padding:2px 32px 10px}
.nav-row{display:flex;align-items:center;gap:22px;overflow-x:auto;white-space:nowrap;scrollbar-width:none;padding:5px 0}
.nav-label{flex:0 0 132px;color:#888;font-size:10px;letter-spacing:.07em}
.nav-row a{font-size:13px}
.nav-row.research-nav a{color:#777}
.section-head{top:calc(var(--header-height) + 20px)}
.project-controls{top:calc(var(--header-height) + 20px)}
.audit-toolbar{top:calc(var(--header-height) + 4px)}
.case-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:24px}
.case-grid h3{font-size:24px;line-height:1.2;margin:7px 0 11px}
.case-grid p{font-size:17px;line-height:1.5}
.case-grid .case-budget{font-size:32px;line-height:1.2;margin:8px 0}
.case-grid .zh,.case-question .zh{font-size:12px}
.case-question{margin-top:25px;padding-top:18px;border-top:1px solid var(--line);font-size:21px;line-height:1.4}
.route-timing{font-size:12px;color:#888;margin-top:20px}
.project-card{display:flex;flex-direction:column}
.project-card .project-pitch{min-height:95px}
.alternative-details{display:grid;grid-template-columns:1fr;gap:16px;margin:0 0 24px}
.alternative-details dt{font-size:12px;color:#888;margin-bottom:4px}
.alternative-details dd{font-size:16px;line-height:1.45;margin:0}
.project-facts{margin-top:auto;grid-template-rows:62px 38px}
.project-facts>span{align-items:baseline}
.project-facts b{font-size:16px;text-align:right}
.valuation-method{margin:22px 0}
.valuation-method .formula{font-size:22px;margin-bottom:9px}
.valuation-method p:not(.formula){font-size:16px;line-height:1.5;color:#666}
.baseline-choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:23px;margin:20px 0}
.baseline-choices h3{font-size:21px;margin:4px 0 7px}
.baseline-choices p{font-size:14px;line-height:1.5;color:#666}
.baseline-choices .zh{font-size:11px}
.valuation-bridge{border-collapse:collapse;width:100%;table-layout:fixed;margin:20px 0 26px;font-size:14px}
.valuation-bridge th,.valuation-bridge td{border-bottom:1px solid var(--line);padding:11px 8px;font-weight:400;text-align:right}
.valuation-bridge th:first-child{width:40%;text-align:left;padding-left:0}
.valuation-bridge thead th{font-size:12px;color:#888}
.valuation-bridge tbody td{font-size:21px}
.valuation-note{font-size:16px;line-height:1.55;margin-top:15px}
.valuation-note.zh{font-size:12px;margin-top:8px}
.valuation-results-heading{font-size:24px;margin-top:29px}
.baseline-rationale{margin:20px 0 27px;padding:0}
.decision-boundaries{margin-top:32px;padding-top:22px;border-top:1px solid var(--line)}
.decision-boundaries>h3{font-size:24px;margin-bottom:13px}
.decision-boundaries>.lead{font-size:18px}
.deeper-focus{font-size:30px;line-height:1.2;margin:9px 0 17px}
.historical-evidence{margin:25px 0 10px;padding:18px 0;border-top:1px solid var(--line)}
.historical-evidence .macro-check{margin-bottom:10px}
.market-coda{padding:17px 0 0;margin:0 0 15px;border-top:1px solid var(--line)}
.market-coda>summary{font-size:20px}
.market-coda .market-subtitle{margin-top:20px}
.bayes-disclosure{padding-top:8px}
.bayes-disclosure>summary{font-size:20px}
.bayes-disclosure>.lead{margin-top:20px}
.research-route-head{margin-bottom:0}
.route-back{font-size:12px;color:#777;margin-top:24px}
