#lab .range-track{min-height:40px}
#lab input[type=range]{min-height:24px;height:24px}
#lab .range-end{padding-top:6px;font-size:9px}
#lab .control-pair .control-top{min-height:43px;gap:4px}
#lab .control-pair .control-top label{font-size:11px}
#lab .control-pair .control-top output{font-size:19px}
#lab .crossover-tick{top:4px;height:16px}
#lab .crossover-tick b{top:20px;font-size:9px}
#lab .advanced-controls{padding:12px 0}
.tipping-detail{border-top:1px solid var(--line);margin-top:22px;padding-top:18px}
#assumptions{scroll-margin-top:145px}

/* Compact recommendation and legible scenario assumptions. */
.recommendation-summary{max-width:620px}
.recommendation-summary .base-label{font-size:10px;padding:0}
.recommendation-summary .thesis{font-size:27px;line-height:1.15;margin:7px 0}
.recommendation-summary .lead{font-size:16px;line-height:1.35}
.recommendation-summary .decision-numbers{margin-top:12px;gap:20px}
.recommendation-summary .decision-numbers strong{font-size:24px;margin-top:0}
.recommendation-summary .decision-numbers .zh{font-size:10px;margin-top:0}
#lab.decision-lab{margin-top:20px;padding-top:18px}
#lab .scenario-card>span{font-size:13px;line-height:1.5;letter-spacing:0}
#lab .scenario-card{padding:12px}
#lab .scenario-card small{margin-bottom:7px;min-height:0}
/* Standalone annual model: full page, no presentation section numbering. */
.annual-page{max-width:1440px;margin:auto;padding:30px 32px 48px}
.annual-page h1{font-size:38px;margin-bottom:8px}
.annual-page .annual-page-head{margin-bottom:24px}
.annual-page .audit-toolbar{margin-top:18px}
.annual-page .table-wrap{max-height:65vh;overflow:auto}
.annual-page .model-params{font-size:14px;color:#666;line-height:1.6}
.annual-page select{border:1px solid #aaa;background:#fff;padding:6px 10px}
@media(max-width:600px){.annual-page{padding:24px 16px}.annual-page h1{font-size:30px}#lab .scenario-card>span{font-size:12px}}

#lab .scenario-card>span{font-size:14px;line-height:1.6}
#lab .scenario-card>span>span{display:block}
#lab .scenario-card>span b{font-weight:600}

/* Audit refinements: opaque compact navigation, legible scope and input guidance. */
.topbar{background:#fff}
.topbar-inner{padding-top:10px;padding-bottom:10px}
.navlinks{padding-top:0;padding-bottom:6px}
.nav-row{padding-top:3px;padding-bottom:3px}
.nav-label{color:#666}
.nav-row.research-nav a{color:#555}
.floating-nav .btn{min-height:32px;padding:6px 10px;font-size:12px}
.scope-tag{display:inline-block;border:1px solid #ccc;padding:2px 6px;font-size:11px;line-height:1.4;color:#555;letter-spacing:0;vertical-align:middle}
.advanced-controls summary .scope-tag{margin-left:8px}
#lab .control-help{font-size:12px;line-height:1.4;color:#595959;margin:3px 0 8px}
.bayes-scope{font-size:13px;line-height:1.5;color:#555;border-left:2px solid #999;padding-left:10px;margin:16px 0}
.bayes-scenarios{margin:0 0 20px}
.bayes-scenarios .validation-table{margin-top:12px}
.bayes-input-table{min-width:600px}
.bayes-input-table th:first-child{width:20%}
.bayes-input-table input{font-size:17px;width:70px}
.bayes-input-table .bayes-product{color:#666;font-variant-numeric:tabular-nums}
#bayesian .input-note{font-size:13px;color:#555}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.metric-current.is-updated{animation:none}}
@media(max-width:850px){.nav-row .nav-label{display:none}.nav-row{gap:16px}}

.spread-note{font-size:13px;line-height:1.5;color:#555;margin:8px 0}
